const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function islandPrintKit(g){const c=g.runtime,colors={wood:'#9db18a',brick:'#c9997e',grain:'#e8d29d',ore:'#aab2bd'},page=(name,body)=>`<article class="kit-page guided-kit"><div class="eyebrow">BOARD STUDIO · ${esc(g.name)}</div><h1>${name}</h1>${body}</article>`;
 const coords=c.tiles.map(t=>({x:Math.sqrt(3)*32*(t.q+t.r/2),y:48*t.r}));const minX=Math.min(...coords.map(p=>p.x))-32,maxX=Math.max(...coords.map(p=>p.x))+32,minY=Math.min(...coords.map(p=>p.y))-36,maxY=Math.max(...coords.map(p=>p.y))+36;
 const svg=`<svg style="width:6.5in;height:auto" viewBox="${minX} ${minY} ${maxX-minX} ${maxY-minY}" role="img" aria-label="Numbered island board">${c.tiles.map((t,i)=>{const p=coords[i];return `<g transform="translate(${p.x},${p.y})"><polygon points="${Array.from({length:6},(_,n)=>`${Math.sin(n*Math.PI/3)*31},${Math.cos(n*Math.PI/3)*31}`).join(' ')}" fill="${colors[t.resource]}" stroke="#555"/><text text-anchor="middle" y="-12" font-size="7">${i+1} · ${esc(t.resource)}</text><text text-anchor="middle" y="6" font-size="17" font-weight="bold">${t.number}</text><text text-anchor="middle" y="20" font-size="6">${c.starts.includes(i)?'P'+(c.starts.indexOf(i)+1)+' START':''}</text></g>`;}).join('')}</svg>`;
 let out=page('Assemble your island',`<p>2 players · First to ${c.targetPoints} points · Original island-settlement rules</p><ol><li>Print at 100% on Letter or A4. Keep the island board intact.</li><li>Cut the colored building markers. Use the side marked 1 for a settlement; replace it with a 2 marker when upgraded to a city.</li><li>Place one settlement per player on their marked starting hex. Buildings occupy hex centers. New settlements must share an edge with your settlement or city.</li><li>Use a household six-sided die. Track resources and turns in pencil on the ledger. The bank is unlimited.</li><li>Start with 2 wood, 2 brick, 2 grain and 1 ore each. Read the quick reference and play one practice round before resetting.</li></ol><div class="calibration">1 inch / 25.4 mm</div><p>3D scenery is decorative; the paper board contains everything needed to play. Optional printable 3D pieces can replace the paper building markers.</p>`);
 out+=page('Island board',svg+`<p>P1: ${esc(c.playerNames[0])} · P2: ${esc(c.playerNames[1])}.</p>`+'<p>Large numbers are production rolls. Small numbers identify hexes. Resource names make the board readable in grayscale.</p>');
 out+=page('Building markers',`<p>Cut on dashed lines. Every building occupies a hex center. Ownership does not change.</p>${c.playerNames.map((n,p)=>`<h2>${esc(n)}</h2><div class="island-paper-markers">${Array.from({length:12},(_,i)=>`<div style="border-color:${c.playerColors[p]}"><strong>${i<6?1:2}</strong><small>P${p+1} · ${i<6?'Settlement':'City'}</small></div>`).join('')}</div>`).join('')}<p>Need more markers? Use scrap paper with a player initial and 1 or 2.</p>`);
 out+=page('Resource ledger & quick reference',`<table class="island-ledger"><thead><tr><th>Player</th><th>Wood</th><th>Brick</th><th>Grain</th><th>Ore</th><th>Points</th></tr></thead><tbody>${c.playerNames.map(n=>`<tr><td>${esc(n)}</td><td>2</td><td>2</td><td>2</td><td>1</td><td>1</td></tr>`).join('')}</tbody></table><h2>Every turn</h2><ol><li>Roll d6. Every matching occupied hex produces for its owner (city: 2).</li><li>If the active player received nothing, choose one resource from the bank.</li><li>Take ONE action: settle, upgrade, trade, or pass.</li><li>Check victory, then switch players.</li></ol><h2>Costs</h2><p>Settlement + connecting road: 1 wood + 1 brick + 1 grain.<br>City upgrade: 2 grain + 2 ore.<br>Bank trade: 3 identical resources for 1 different resource.</p><h2>Completed turns</h2><p>${Array.from({length:c.turnLimit},(_,i)=>`${i+1} □`).join('　')}</p>`);
 out+=page('Rules manual',Object.entries(g.rules).map(([key,text])=>`<section class="paper-rule"><h2>${esc(key[0].toUpperCase()+key.slice(1))}</h2><p>${esc(text)}</p></section>`).join(''));return out;}
